}

void Hex::writeUInt32(v_uint32 value, p_char8 buffer){
  writeUInt16(static_cast<v_uint16>(value >> 16), buffer);
  writeUInt16(static_cast<v_uint16>(value & 0xffff), buffer + 4);
}

